def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'D'
    if n == 4:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    if n == 5:
        if opp[4] == 'D':
            return 'C'
        else:
            return 'D'

    my_def_count = 0
    opp_def_count = 0
    retaliate = 0
    forgive = 0
    last_my_def = -1
    for i in range(n):
        my_act, opp_act = history[i]
        if my_act == 'D':
            my_def_count += 1
            last_my_def = i
        if opp_act == 'D':
            opp_def_count += 1
        if i < n - 1:
            if my_act == 'D':
                if history[i+1][1] == 'D':
                    retaliate += 1
                else:
                    forgive += 1

    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining == 2:
        if retaliate > forgive:
            return 'C'
        else:
            return 'D'

    opp_coop_rate = (n - opp_def_count) / n

    if opp_coop_rate < 0.3:
        return 'D'

    last_my, last_opp = history[-1]

    if opp_def_count == 0:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C':
            if opp_coop_rate > 0.8:
                return 'C'
            else:
                return 'D'
        else:
            return 'C'

    if last_my == 'D':
        return 'C'

    rounds_since_my_def = n - 1 - last_my_def if last_my_def >= 0 else n

    if my_def_count > 0 and forgive > retaliate and opp_coop_rate > 0.7:
        if rounds_since_my_def >= 3:
            return 'D'

    return 'C'
